-- Tambah kolom warna_status pada lamaran agar frontend bisa menampilkan
-- warna yang konsisten untuk masing-masing status (terutama 'Ditolak' -> merah).
-- Safe: hanya ADD COLUMN jika belum ada.
SET @col_exists := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
                    WHERE TABLE_SCHEMA = DATABASE()
                      AND TABLE_NAME = 'lamaran'
                      AND COLUMN_NAME = 'warna_status');
SET @ddl := IF(@col_exists = 0,
               'ALTER TABLE `lamaran` ADD COLUMN `warna_status` VARCHAR(20) NULL AFTER `tahap`',
               'SELECT 1');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

