-- Set warna_status per status lamaran. Frontend cukup membaca kolom ini:
--   Diterima          -> '#198754' (hijau)
--   Ditolak           -> '#dc3545' (MERAH)
--   Screaning         -> '#6c757d' (abu-abu netral, masih proses awal)
--   InterviewPertama  -> '#0d6efd' (biru)
--   InterviewKedua    -> '#6610f2' (ungu)
--   Psikotes          -> '#fd7e14' (oranye)
UPDATE `lamaran` SET `warna_status` = CASE
    WHEN `status` = 'Diterima'         THEN '#198754'
    WHEN `status` = 'Ditolak'          THEN '#dc3545'
    WHEN `status` = 'Screaning'        THEN '#6c757d'
    WHEN `status` = 'InterviewPertama' THEN '#0d6efd'
    WHEN `status` = 'InterviewKedua'  THEN '#6610f2'
    WHEN `status` = 'Psikotes'         THEN '#fd7e14'
    ELSE '#6c757d'
END
WHERE `warna_status` IS NULL OR `warna_status` = '';

-- ============================================================
-- FIX v4: koreksi kolom `tahap` untuk lamaran berstatus 'Ditolak'.
-- Sebelumnya tahap='Ditolak' (literal), padahal seharusnya berisi
-- tahap di mana pelamar DITOLAK. Update ini disinkronkan dengan
-- data jadwal_wawancara & hasil_psikotes di bawah.
-- ============================================================
UPDATE `lamaran` SET `tahap` = 'Psikotes'         WHERE `id` = 2  AND `status` = 'Ditolak';
UPDATE `lamaran` SET `tahap` = 'Screaning'        WHERE `id` = 3  AND `status` = 'Ditolak';
UPDATE `lamaran` SET `tahap` = 'InterviewPertama' WHERE `id` = 8  AND `status` = 'Ditolak';
UPDATE `lamaran` SET `tahap` = 'Psikotes'         WHERE `id` = 9  AND `status` = 'Ditolak';
UPDATE `lamaran` SET `tahap` = 'InterviewPertama' WHERE `id` = 14 AND `status` = 'Ditolak';
UPDATE `lamaran` SET `tahap` = 'Psikotes'         WHERE `id` = 15 AND `status` = 'Ditolak';
UPDATE `lamaran` SET `tahap` = 'Screaning'        WHERE `id` = 20 AND `status` = 'Ditolak';
UPDATE `lamaran` SET `tahap` = 'InterviewPertama' WHERE `id` = 21 AND `status` = 'Ditolak';

-- ============================================================
-- v7: Sinkronisasi kolom `skor` di lamaran.
-- Skor mulai terisi SETELAH pelamar LULUS Interview Pertama
-- (yaitu pelamar yang TAHAP-nya = InterviewKedua atau lebih tinggi).
--
-- Logika:
--   Screaning                          -> NULL  (belum tes apa-apa)
--   InterviewPertama                   -> NULL  (masih dites)
--   InterviewKedua                     -> 70-80 (sudah lulus Interview 1)
--   Psikotes (scheduled, belum final)  -> 75-85 (sudah lulus 2 interview)
--   Diterima                           -> 85    (final, Lolos Psikotes)
--   Ditolak @ Psikotes                 -> 55    (final, Gagal Psikotes)
--   Ditolak @ InterviewPertama         -> NULL  (gugur sebelum dapat skor)
--   Ditolak @ Screaning                -> NULL  (gugur sebelum dapat skor)
-- ============================================================

-- Step 1: Reset semua skor ke NULL dulu (safe default)
UPDATE `lamaran` SET `skor` = NULL;

-- Step 2: Skor sementara untuk pelamar di tahap InterviewKedua
-- (sudah lulus Interview Pertama). Skor ini diambil dari hasil Interview
-- Pertama yang menghasilkan kelolosan ke Interview Kedua.
UPDATE `lamaran` SET `skor` = 75 WHERE `id` = 10;  -- Tika Wulandari, Marketing Specialist

-- Step 3: Skor sementara untuk pelamar di tahap Psikotes (scheduled,
-- belum final). Skor ini gabungan hasil Interview Pertama + Interview
-- Kedua yang keduanya menghasilkan kelolosan ke tahap Psikotes.
UPDATE `lamaran` SET `skor` = 80 WHERE `id` = 5;   -- Agus Pribadi, Staff Adm Korporat
UPDATE `lamaran` SET `skor` = 78 WHERE `id` = 11;  -- Andi Wijaya, Marketing Specialist
UPDATE `lamaran` SET `skor` = 82 WHERE `id` = 16;  -- Dewi Lestari, Staf General Affairs
UPDATE `lamaran` SET `skor` = 80 WHERE `id` = 23;  -- Andi Wijaya, Legal Officer

-- Step 4: Skor final untuk pelamar yang sudah menyelesaikan Psikotes.
-- Diambil dari hasil_psikotes.skor_akhir:
--   Diterima (Lolos Psikotes) -> 85
--   Ditolak @ Psikotes        -> 55
UPDATE `lamaran` SET `skor` = 85 WHERE `id` = 1;   -- Dewi Lestari, Diterima
UPDATE `lamaran` SET `skor` = 55 WHERE `id` = 2;   -- Budi Santoso, Ditolak @ Psikotes
UPDATE `lamaran` SET `skor` = 85 WHERE `id` = 7;   -- Siti Rahmawati, Diterima
UPDATE `lamaran` SET `skor` = 55 WHERE `id` = 9;   -- Fajar Nugroho, Ditolak @ Psikotes
UPDATE `lamaran` SET `skor` = 85 WHERE `id` = 13;  -- Fajar Nugroho, Diterima
UPDATE `lamaran` SET `skor` = 55 WHERE `id` = 15;  -- Agus Pribadi, Ditolak @ Psikotes
UPDATE `lamaran` SET `skor` = 85 WHERE `id` = 19;  -- Rina Melati, Diterima

-- Step 5: Safety net — pastikan pelamar Ditolak @ InterviewPertama
-- dan Ditolak @ Screaning PASTI skor=NULL, serta pelamar di Screaning /
-- InterviewPertama (scheduled, belum lulus) PASTI skor=NULL.
UPDATE `lamaran` SET `skor` = NULL
WHERE `status` IN ('Screaning', 'InterviewPertama')
   OR (`status` = 'Ditolak' AND `tahap` IN ('InterviewPertama', 'Screaning'));

-- ============================================================
-- VIEW siap pakai untuk chart "Status Kandidat" di dashboard admin.
-- Pakai: SELECT label, jumlah, warna FROM v_lamaran_status_pipeline
--        ORDER BY urutan;
-- Urutan pipeline: Screaning -> InterviewPertama -> InterviewKedua
--                  -> Psikotes -> Diterima -> Ditolak
-- ============================================================
DROP VIEW IF EXISTS `v_lamaran_status_pipeline`;
CREATE VIEW `v_lamaran_status_pipeline` AS
SELECT 1 AS urutan, 'Screaning'        AS label, COUNT(*) AS jumlah, '#6c757d' AS warna
FROM `lamaran` WHERE `status` = 'Screaning'
UNION ALL
SELECT 2, 'InterviewPertama', COUNT(*), '#0d6efd'
FROM `lamaran` WHERE `status` = 'InterviewPertama'
UNION ALL
SELECT 3, 'InterviewKedua', COUNT(*), '#6610f2'
FROM `lamaran` WHERE `status` = 'InterviewKedua'
UNION ALL
SELECT 4, 'Psikotes', COUNT(*), '#fd7e14'
FROM `lamaran` WHERE `status` = 'Psikotes'
UNION ALL
SELECT 5, 'Diterima', COUNT(*), '#10b981'
FROM `lamaran` WHERE `status` = 'Diterima'
UNION ALL
SELECT 6, 'Ditolak', COUNT(*), '#ef4444'
FROM `lamaran` WHERE `status` = 'Ditolak';

-- ============================================================
-- VIEW v_status_kandidat (3 kategori) untuk StatusCard.jsx minimal.
-- Urutan: 1=Diterima (hijau), 2=Ditolak (merah), 3=Pending (oranye).
-- Pending = semua lamaran yang belum mencapai status final.
-- ============================================================
DROP VIEW IF EXISTS `v_status_kandidat`;
CREATE VIEW `v_status_kandidat` AS
SELECT 1 AS urutan, 'Diterima' AS label, COUNT(*) AS jumlah
FROM `lamaran` WHERE `status` = 'Diterima'
UNION ALL
SELECT 2, 'Ditolak', COUNT(*)
FROM `lamaran` WHERE `status` = 'Ditolak'
UNION ALL
SELECT 3, 'Pending', COUNT(*)
FROM `lamaran`
WHERE `status` NOT IN ('Diterima', 'Ditolak');

