-- ============================================================
-- v9: Update status_kehadiran jadwal_wawancara.
-- Ditambahkan di akhir supaya tidak mengganggu INSERT awal.
-- ============================================================

-- A. 3 jadwal jadi TIDAK HADIR
-- Sebelumnya status='completed', status_kehadiran='hadir'. Sekarang
-- ubah jadi 'tidak_hadir' dengan alasan.
UPDATE `jadwal_wawancara` SET
  `status_kehadiran` = 'tidak_hadir',
  `alasan_tidak_hadir` = 'Sakit - surat dokter terlampir',
  `updated_at` = `tanggal_waktu`
WHERE `id` = 6;   -- Andi Wijaya, Staff Adm Korporat, InterviewPertama

UPDATE `jadwal_wawancara` SET
  `status_kehadiran` = 'tidak_hadir',
  `alasan_tidak_hadir` = 'Ada keperluan mendadak di kantor',
  `updated_at` = `tanggal_waktu`
WHERE `id` = 16;  -- Tika Wulandari, Marketing Specialist, InterviewKedua

UPDATE `jadwal_wawancara` SET
  `status_kehadiran` = 'tidak_hadir',
  `alasan_tidak_hadir` = 'Keluarga sakit - di luar kota',
  `updated_at` = `tanggal_waktu`
WHERE `id` = 32;  -- Dewi Lestari, Staf General Affairs, Psikotes

-- B. 3 jadwal jadi HADIR TAPI BELUM KONFIRMASI SELESAI
-- Sebelumnya status='scheduled', dikonfirmasi_oleh_pelamar=0,
-- status_kehadiran='pending'. Sekarang pelamar sudah konfirmasi hadir,
-- tapi interview belum dilaksanakan/marked done.
UPDATE `jadwal_wawancara` SET
  `dikonfirmasi_oleh_pelamar` = 1,
  `status_kehadiran` = 'hadir',
  `waktu_konfirmasi` = `tanggal_waktu`,
  `updated_at` = `tanggal_waktu`
WHERE `id` = 7;   -- Agus Pribadi, Staff Adm Korporat, Psikotes

UPDATE `jadwal_wawancara` SET
  `dikonfirmasi_oleh_pelamar` = 1,
  `status_kehadiran` = 'hadir',
  `waktu_konfirmasi` = `tanggal_waktu`,
  `updated_at` = `tanggal_waktu`
WHERE `id` = 22;  -- Andi Wijaya, Marketing Specialist, Psikotes

UPDATE `jadwal_wawancara` SET
  `dikonfirmasi_oleh_pelamar` = 1,
  `status_kehadiran` = 'hadir',
  `waktu_konfirmasi` = `tanggal_waktu`,
